            apu: Apu::new(),
            dma: Dma::new(),
            timers: Timers::new(),
            keypad: Keypad::new(),
            serial: SerialStub::new(),
            irq: Irq::new(),
            cart: Cart::new(rom),
            access_cycles: 0,
