use crate::bus::Bus;

/// CPSR mode bits 0-4 (gbatek: ARM CPU Register Set).
pub const MODE_USER: u32 = 0x10;
pub const MODE_FIQ: u32 = 0x11;
pub const MODE_IRQ: u32 = 0x12;
pub const MODE_SUPERVISOR: u32 = 0x13;
pub const MODE_ABORT: u32 = 0x17;
pub const MODE_UNDEFINED: u32 = 0x1B;
pub const MODE_SYSTEM: u32 = 0x1F;

pub const CPSR_THUMB: u32 = 1 << 5; // T: 0 = ARM, 1 = THUMB state
pub const CPSR_FIQ_DISABLE: u32 = 1 << 6; // F
pub const CPSR_IRQ_DISABLE: u32 = 1 << 7; // I

pub const PROGRAM_COUNTER: usize = 15; // R15
pub const LINK_REGISTER: usize = 14; // R14
pub const STACK_POINTER: usize = 13; // R13

pub struct Cpu {
    /// R0-R15 of the current mode.
    pub registers: [u32; 16],
    /// Current program status register.
    pub cpsr: u32,
    /// Saved program status register of the current mode.
    pub spsr: u32,
}

impl Cpu {
    /// Reset state: Supervisor mode, ARM state, IRQ and FIQ disabled, PC at the reset vector 0.
    pub fn new() -> Self {
        Cpu {
            registers: [0; 16],
            cpsr: MODE_SUPERVISOR | CPSR_IRQ_DISABLE | CPSR_FIQ_DISABLE,
            spsr: 0,
        }
    }

    /// Execute one instruction (or one idle halt slice) and return the cycles it used,
    /// including the bus access cycles from `bus.take_access_cycles()`. Stub: 1 cycle.
    pub fn step(&mut self, bus: &mut Bus) -> u32 {
        1 + bus.take_access_cycles()
    }
}

//! Barrel shifter, add/subtract with flags and condition evaluation
//! (gbatek: ARM CPU Flags & Condition Field, ARM Opcodes: Data Processing (ALU)).
//!
//! Phase 0 stub; filled in by the Phase 1 CPU core agent.

//! ARM (32-bit) instruction decode and execute (gbatek: ARM Instruction Summary and ARM Opcodes).
//!
//! Phase 0 stub; filled in by the Phase 1 ARM agent.

//! THUMB (16-bit) instruction decode and execute (gbatek: THUMB Instruction Summary and THUMB Opcodes).
//!
//! Phase 0 stub; filled in by the Phase 1 THUMB agent.

//! The whole machine: CPU plus bus (which owns every other component), and the frame loop.
//!
//! Events between components (PPU -> DMA, timers -> APU, APU -> DMA) are plain method calls here,
//! so no component holds a reference to another.

use crate::bus::Bus;
use crate::cpu::Cpu;
use crate::dma;
use crate::ppu::CYCLES_PER_LINE;
use crate::scheduler::Scheduler;

/// 228 lines x 1232 cycles (gbatek: LCD Dimensions and Timings).
pub const CYCLES_PER_FRAME: u32 = 280_896;

/// Scanline at whose start `run_frame` returns. 160 = frame ends at the start of VBlank (the
/// picture is complete and the game's VBlank handler runs after the host sets the next keys);
/// 0 = frame ends at the start of the next frame's drawing. Must match Mesen2's frame boundary:
/// the integrator compares early frames with the reference and changes this one value if needed.
/// Every frame is exactly `CYCLES_PER_FRAME` long; only the first frame after reset is shorter
/// (it runs from line 0 to this line).
pub const FRAME_END_LINE: u32 = 160;

pub struct Gba {
    pub cpu: Cpu,
    pub bus: Bus,
    pub scheduler: Scheduler,
    /// Cycles left before the current frame ends; overshoot carries into the next frame.
    cycles_until_frame_end: i64,
}

impl Gba {
    /// Power-on state with `rom` inserted. The CPU starts at the BIOS reset vector.
    pub fn new(rom: &[u8]) -> Self {
        let first_frame_cycles = match FRAME_END_LINE * CYCLES_PER_LINE {
            0 => CYCLES_PER_FRAME,
            cycles => cycles,
        };
        Gba {
            cpu: Cpu::new(),
            bus: Bus::new(rom),
            scheduler: Scheduler::new(),
            cycles_until_frame_end: first_frame_cycles as i64,
        }
    }

    /// Latch the host key state (ABI bit order, active high).
    pub fn set_keys(&mut self, pressed_keys: u32) {
        self.bus.keypad.set_keys(pressed_keys);
    }

    /// Run until the frame boundary (see `FRAME_END_LINE`).
    pub fn run_frame(&mut self) {
        while self.cycles_until_frame_end > 0 {
            let mut cycles = self.cpu.step(&mut self.bus);
            cycles += dma::run_pending_transfers(&mut self.bus);
            self.advance_components(cycles);
            self.cycles_until_frame_end -= cycles as i64;
        }
        self.cycles_until_frame_end += CYCLES_PER_FRAME as i64;
    }

    /// Advance PPU, timers and APU by `cycles` and route their events.
    fn advance_components(&mut self, cycles: u32) {
        let bus = &mut self.bus;
        self.scheduler.advance(cycles);

        let ppu_events = bus.ppu.step(cycles, &mut bus.irq);
        if ppu_events.hblank_started {
            bus.dma.notify_hblank();
        }
        if ppu_events.vblank_started {
            bus.dma.notify_vblank();
        }

        let overflowed_timers = bus.timers.step(cycles, &mut bus.irq);
        for timer_index in 0..4 {
            if overflowed_timers & (1 << timer_index) == 0 {
                continue;
            }
            let fifo_requests = bus.apu.on_timer_overflow(timer_index);
            for fifo_index in 0..2 {
                if fifo_requests & (1 << fifo_index) != 0 {
                    bus.dma.notify_fifo_request(fifo_index);
                }
            }
        }

        bus.apu.step(cycles);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frames_keep_line_timing_aligned() {
        let mut gba = Gba::new(&[]);
        gba.run_frame();
        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
        let after_first = gba.scheduler.total_cycles;
        gba.run_frame();
        assert_eq!(gba.scheduler.total_cycles - after_first, CYCLES_PER_FRAME as u64);
        assert_eq!(gba.bus.ppu.vcount as u32, FRAME_END_LINE % 228);
    }

    #[test]
    fn vblank_irq_is_requested_when_enabled() {
        let mut gba = Gba::new(&[]);
        gba.bus.write16(0x0400_0004, 1 << 3); // DISPSTAT: VBlank IRQ enable
        gba.run_frame();
        gba.run_frame();
        assert_ne!(gba.bus.irq.interrupt_flags & 1, 0);
    }
}

